lemma castDown_lt_iff {m : ℕ} (hm : 2 ≤ m) {v w : Fin m}
    (hv : (v : ℕ) < m - 1) (hw : (w : ℕ) < m - 1) :
    castDown m hm v < castDown m hm w ↔ v < w

lemma castDown_injOn {m : ℕ} (hm : 2 ≤ m) {v w : Fin m}
    (hv : (v : ℕ) < m - 1) (hw : (w : ℕ) < m - 1)
    (h : castDown m hm v = castDown m hm w) : v = w
